using System.Collections.Concurrent;
using System.Runtime.CompilerServices;
using Zenith.Logging;
using Zenith.Rulebook;

namespace Zenith.World;

/// <summary>
/// The world: the <see cref="WorldColumn"/>s that are resident right now, loaded from <see cref="IChunkStorage"/> or
/// generated by the dimension's <see cref="ITerrainProvider"/> (ADR §167). A column is the single source of truth for its
/// blocks and block entities; terrain is consulted once, when a column has no stored copy. Reads are lock-free; writes
/// belong to the GameLoop. Edited columns are persisted write-behind (<see cref="PersistDirtyColumns"/>, eviction, shutdown),
/// untouched ones are dropped and regenerated on demand.
/// </summary>
sealed class World
{
    private readonly IChunkStorage _storage;
    private readonly Dimension _overworld;
    private readonly ConcurrentDictionary<ChunkCoord, WorldColumn> _columns = new();
    private readonly WorldGenerationBroker _generationBroker;
    private readonly int _generationWorkers;
    private readonly ILogger? _logger;
    private int _syncLoads;

    /// <summary>The server logger this world was built with (null in headless tests), for gameplay that reports about the world.</summary>
    public ILogger? Logger => _logger;
    private readonly WorldGenerationDiagnostics? _generationDiagnostics;

    /// <summary>Game rules of this world (defaults from the stock BDS capture, restored from storage at boot).</summary>
    public GameRules Rules { get; } = GameRuleDefaults.Create();

    public FloorDropStore FloorDrops { get; }
    public ChestStore Chests { get; }
    public GravityPendingStore GravityPending { get; }
    public FallingBlockStore FallingBlocks { get; }

    /// <summary>Cells written since the last tick whose neighbourhood must be re-evaluated (ADR §164).</summary>
    public BlockUpdateQueue BlockUpdates { get; } = new();

    /// <summary>Cells due for re-evaluation at a later tick (ADR §164).</summary>
    public ScheduledTicks ScheduledTicks { get; } = new();

    /// <summary>Per-chunk viewer refcount driving eviction (ADR §114) — see <see cref="ChunkResidencyIndex"/>.</summary>
    public ChunkResidencyIndex ChunkResidency { get; } = new();

    /// <summary>Default playable dimension (only one until Nether/End ADR).</summary>
    public Dimension Overworld => _overworld;

    /// <summary>Columns resident in RAM now.</summary>
    public int LoadedColumnCount => _columns.Count;

    /// <summary>
    /// Columns the tick thread had to load or generate itself because a read or write reached a cell nobody had streamed.
    /// Zero in steady state; a rising count means gameplay is touching chunks that are not resident.
    /// </summary>
    public int SyncLoadCount => Volatile.Read(ref _syncLoads);

    /// <summary>Feet Y for join/respawn above generated terrain at (x,z) — ignores player edits.</summary>
    public int SampleSpawnFeetY(int x, int z) => _overworld.Terrain.SampleSpawnFeetY(x, z);

    public OverworldBiomeKind SampleBiome(int x, int z) => _overworld.Terrain.SampleBiome(x, z);

    public World(
        IChunkStorage storage,
        ILogger? logger = null,
        ITerrainProvider? terrain = null,
        WorldGenerationDiagnostics? generationDiagnostics = null,
        int generationWorkers = 1)
    {
        if (generationWorkers is < 1 or > 64)
            throw new ArgumentOutOfRangeException(nameof(generationWorkers), generationWorkers, "Generation workers must be 1..64.");

        _storage = storage;
        _overworld = Dimension.CreateOverworld(terrain ?? FlatTerrainProvider.Instance);
        _logger = logger;
        _generationDiagnostics = generationDiagnostics;
        _generationWorkers = generationWorkers;
        _generationBroker = new WorldGenerationBroker(generationWorkers, GenerateColumnCoreAsync, generationDiagnostics);
        FloorDrops = new FloorDropStore(logger);
        Chests = new ChestStore(this);
        GravityPending = new GravityPendingStore(logger);
        FallingBlocks = new FallingBlockStore(logger);
    }

    /// <summary>
    /// Applies the stored game rules (if any) on top of the defaults. Boot only. A stored list that does not decode
    /// is reported and ignored (the defaults stay), never half-applied; rules this build does not know are named.
    /// </summary>
    public void LoadGameRules()
    {
        var blob = _storage.GetGameRulesAsync().AsTask().GetAwaiter().GetResult();
        if (blob is null) return;
        List<GameRule> stored;
        try
        {
            stored = GameRuleCodec.FromBytes(blob);
        }
        catch (Exception e) when (e is InvalidDataException or EndOfStreamException or ArgumentException)
        {
            _logger?.Warning($"Stored game rules are unreadable ({e.Message}); using the defaults.");
            return;
        }

        Rules.Restore(stored, out var ignored);
        if (ignored.Count > 0)
            _logger?.Warning($"Stored game rules ignored (unknown name or changed type): {string.Join(", ", ignored)}.");
    }

    /// <summary>
    /// Write-behind: the storage call enqueues the write and returns; nobody waits for it. A ValueTask must still be consumed, so a
    /// completed one is read and a pending or faulted one is observed here, where a failure is logged instead of vanishing as an
    /// unobserved task exception.
    /// </summary>
    private void WriteBehind(ValueTask write, string what)
    {
        if (write.IsCompletedSuccessfully)
        {
            write.GetAwaiter().GetResult();
            return;
        }

        _ = ObserveWriteAsync(write, what);
    }

    private async Task ObserveWriteAsync(ValueTask write, string what)
    {
        try
        {
            await write.ConfigureAwait(false);
        }
        catch (Exception exception)
        {
            _logger?.Warning($"World write-behind '{what}' failed: {exception.Message}");
        }
    }

    public void PersistGameRules() => WriteBehind(_storage.PutGameRulesAsync(GameRuleCodec.ToBytes(Rules.Snapshot)), "PutGameRules");

    public void PersistInventory(Player.Player player)
    {
        if (!player.IdentityStable) return;
        WriteBehind(_storage.PutInventoryAsync(player.Uuid, PlayerInventorySave.Pack(player)), "PutInventory");
    }

    /// <summary>Raw Put for tests / loaders — prefer <see cref="PersistInventory(Player.Player)"/> on live sessions.</summary>
    public void PersistInventory(Guid uuid, Player.PlayerInventory inventory) =>
        WriteBehind(_storage.PutInventoryAsync(uuid, inventory.PackMainBlob()), "PutInventory");

    public bool TryLoadInventory(Guid uuid, Player.PlayerInventory inventory)
    {
        var blob = _storage.GetInventoryAsync(uuid).AsTask().GetAwaiter().GetResult();
        return blob is not null && PlayerInventorySave.TryLoad(blob, inventory);
    }

    public bool TryLoadInventory(Player.Player player)
    {
        var blob = _storage.GetInventoryAsync(player.Uuid).AsTask().GetAwaiter().GetResult();
        return blob is not null && PlayerInventorySave.TryLoad(blob, player.Inventory, player.Windows);
    }

    public void PersistArmor(Player.Player player)
    {
        if (!player.IdentityStable) return;
        WriteBehind(_storage.PutArmorAsync(player.Uuid, player.Inventory.PackArmorBlob()), "PutArmor");
    }

    public bool TryLoadArmor(Guid uuid, Player.PlayerInventory inventory)
    {
        var blob = _storage.GetArmorAsync(uuid).AsTask().GetAwaiter().GetResult();
        return blob is not null && inventory.TryLoadArmorFromBlob(blob);
    }

    public void PersistOffhand(Player.Player player)
    {
        if (!player.IdentityStable) return;
        WriteBehind(_storage.PutOffhandAsync(player.Uuid, player.Inventory.PackOffhandBlob()), "PutOffhand");
    }

    public bool TryLoadOffhand(Guid uuid, Player.PlayerInventory inventory)
    {
        var blob = _storage.GetOffhandAsync(uuid).AsTask().GetAwaiter().GetResult();
        return blob is not null && inventory.TryLoadOffhandFromBlob(blob);
    }

    /// <summary>Quit / gamemode Persist — skips unstable identity (ADR §60).</summary>
    public void PersistPlayerData(Player.Player player)
    {
        if (!player.IdentityStable) return;
        // A persisted health of 0 would fail TryUnpack's own corruption guard on the next load
        // (health must be positive — a hydrated player must never load already-dead). Disconnecting
        // mid-death-screen (before CompleteRespawn ran) is the one real path that could otherwise
        // hit this: persist as if already respawned rather than losing the whole blob (pose/XP too)
        // to a validation rejection.
        var health = player.IsDead ? player.MaxHealth : player.Health;
        var blob = PlayerDataBlob.Pack(
            player.PositionX,
            player.PositionY,
            player.PositionZ,
            player.Yaw,
            player.Pitch,
            player.GameMode,
            player.ExperienceLevel,
            player.ExperiencePoints,
            health,
            player.Hunger,
            player.Saturation,
            player.Exhaustion);
        WriteBehind(_storage.PutPlayerDataAsync(player.Uuid, blob), "PutPlayerData");
    }

    /// <summary>
    /// Login hydrate. False = miss / corrupt / OOB → caller keeps terrain spawn + config GameMode.
    /// </summary>
    public bool TryLoadPlayerData(
        Guid uuid, out float x, out float y, out float z, out float yaw, out float pitch, out Player.GameMode mode,
        out int experienceLevel, out int experiencePoints,
        out float health, out float hunger, out float saturation, out float exhaustion)
    {
        x = y = z = yaw = pitch = 0;
        mode = Player.GameMode.Survival;
        experienceLevel = 0;
        experiencePoints = 0;
        health = 20f;
        hunger = 20f;
        saturation = 5f;
        exhaustion = 0f;
        var blob = _storage.GetPlayerDataAsync(uuid).AsTask().GetAwaiter().GetResult();
        return blob is not null && PlayerDataBlob.TryUnpack(
            blob, out x, out y, out z, out yaw, out pitch, out mode, out experienceLevel, out experiencePoints,
            out health, out hunger, out saturation, out exhaustion);
    }

    /// <summary>
    /// True when feet + eye cell are air (standing room). Used to heal flat-era pd: into noise hills.
    /// </summary>
    public bool IsSpawnFeetClear(int blockX, int feetY, int blockZ) =>
        GetBlock(blockX, feetY, blockZ) == AirRuntimeId &&
        GetBlock(blockX, feetY + 1, blockZ) == AirRuntimeId;

    /// <summary>
    /// If a saved pose is buried / flooded, finds the feet Y that stands on the surface at the same XZ.
    /// Returns true (with <paramref name="healedY"/>) when the pose needs to change; the caller applies it and persists. A pure
    /// query: the world never writes player state.
    /// </summary>
    public bool TryHealSpawnFeet(float x, float y, float z, out float healedY)
    {
        healedY = y;
        var bx = (int)MathF.Floor(x);
        var by = (int)MathF.Floor(y);
        var bz = (int)MathF.Floor(z);
        if (IsSpawnFeetClear(bx, by, bz))
            return false;

        var candidate = SampleSpawnFeetY(bx, bz);
        if (candidate == by && IsSpawnFeetClear(bx, candidate, bz))
            return false;

        healedY = candidate;
        return true;
    }

    /// <summary>Persist every edited column, then await in-flight writes — shutdown only (ADR §41).</summary>
    public ValueTask FlushPersistenceAsync(CancellationToken cancellationToken = default)
    {
        PersistDirtyColumns(int.MaxValue);
        return _storage.FlushAsync(cancellationToken);
    }

    // ---- columns ----

    /// <summary>The resident column, or false when nobody has loaded it (never loads).</summary>
    public bool TryGetLoadedColumn(int chunkX, int chunkZ, out WorldColumn column) =>
        _columns.TryGetValue(new ChunkCoord(chunkX, chunkZ), out column!);

    /// <summary>
    /// The column a client or the gameplay needs, loaded from storage or generated on first touch. Safe to call from any
    /// thread: concurrent first touches of one chunk share a single load (the broker coalesces them).
    /// </summary>
    public async ValueTask<WorldColumn> GetOrCreateColumnAsync(int chunkX, int chunkZ, CancellationToken ct = default)
    {
        ct.ThrowIfCancellationRequested();
        if (_columns.TryGetValue(new ChunkCoord(chunkX, chunkZ), out var resident))
        {
            _generationDiagnostics?.RecordCacheHit();
            return resident;
        }

        var generationScope = _generationDiagnostics is null
            ? default(WorldGenerationDiagnostics.ColumnScope)
            : _generationDiagnostics.BeginColumn();
        using (generationScope)
        {
            var request = await _generationBroker.RequestAsync(new ChunkCoord(chunkX, chunkZ)).ConfigureAwait(false);
            if (request.Coalesced) _generationDiagnostics?.RecordCoalesced();
            return await request.Task.WaitAsync(ct).ConfigureAwait(false);
        }
    }

    private async ValueTask<WorldColumn> GenerateColumnCoreAsync(ChunkCoord coord)
    {
        try
        {
            if (_columns.TryGetValue(coord, out var resident)) return resident;
            var stored = await _storage.GetColumnAsync(coord, CancellationToken.None).ConfigureAwait(false);
            var column = Publish(BuildColumn(coord, stored));
            _ = column.GetWire(); // serialise here, on the worker, so the tick that queues it for a client finds the bytes ready
            return column;
        }
        catch
        {
            _generationDiagnostics?.RecordFailed();
            throw;
        }
    }

    /// <summary>A column from its stored bytes, or from terrain when there are none (or they cannot be read).</summary>
    private WorldColumn BuildColumn(ChunkCoord coord, byte[]? stored)
    {
        if (stored is not null)
        {
            try
            {
                var column = ColumnCodec.Decode(stored, coord, _overworld.WireId, Blocks.Palette);
                _generationDiagnostics?.RecordLoaded();
                return column;
            }
            catch (InvalidDataException exception)
            {
                _logger?.Warning($"Stored column {coord.X},{coord.Z} is unreadable ({exception.Message}); regenerating it.");
            }
        }

        _generationDiagnostics?.RecordGenerated();
        var terrain = _overworld.Terrain.GetBaseColumn(coord.X, coord.Z);
        var generated = new WorldColumn(coord, _overworld.WireId, terrain.BiomeNetworkId);
        for (var i = 0; i < terrain.Sections.Length; i++)
            if (terrain.Sections[i] is { } section) generated.SetSection(i, section);
        return generated;
    }

    /// <summary>Makes a built column resident. If another path got there first its column wins and this one is dropped.</summary>
    private WorldColumn Publish(WorldColumn column) => _columns.GetOrAdd(column.Coord, column);

    /// <summary>The column holding block (x, z); loaded on the calling thread if nobody streamed it yet.</summary>
    private WorldColumn ColumnAt(int x, int z)
    {
        var coord = new ChunkCoord(ToChunk(x), ToChunk(z));
        if (_columns.TryGetValue(coord, out var column)) return column;

        Interlocked.Increment(ref _syncLoads);
        var stored = _storage.GetColumnAsync(coord).AsTask().GetAwaiter().GetResult();
        return Publish(BuildColumn(coord, stored));
    }

    public async ValueTask<IReadOnlyList<WorldColumn>> GetRadiusAsync(int centerX, int centerZ, int radius, CancellationToken ct = default)
    {
        var results = new List<WorldColumn>();
        await foreach (var column in StreamRadiusAsync(centerX, centerZ, radius, ct)
                           .ConfigureAwait(false))
            results.Add(column);
        return results;
    }

    /// <summary>
    /// Reads a square radius in deterministic chunk order without materializing the complete
    /// radius. At most a small worker-sized batch is retained by this iterator; the caller's
    /// consumption rate therefore applies backpressure to generation and serialization stages.
    /// </summary>
    public async IAsyncEnumerable<WorldColumn> StreamRadiusAsync(
        int centerX,
        int centerZ,
        int radius,
        [EnumeratorCancellation] CancellationToken ct = default)
    {
        if (radius < 0)
            throw new ArgumentOutOfRangeException(nameof(radius), radius, "Radius must be non-negative.");

        var batch = new List<Task<WorldColumn>>(Math.Max(_generationWorkers * 2, 1));
        foreach (var (x, z) in EnumerateRadius(centerX, centerZ, radius))
        {
            ct.ThrowIfCancellationRequested();
            batch.Add(GetOrCreateColumnAsync(x, z, ct).AsTask());
            if (batch.Count < batch.Capacity)
                continue;

            var completed = await Task.WhenAll(batch).ConfigureAwait(false);
            foreach (var column in completed)
                yield return column;
            batch.Clear();
        }

        if (batch.Count == 0)
            yield break;

        var tail = await Task.WhenAll(batch).ConfigureAwait(false);
        foreach (var column in tail)
            yield return column;
    }

    /// <summary>Enumerates a square in center-out order without retaining the complete radius.</summary>
    private static IEnumerable<(int X, int Z)> EnumerateRadius(int centerX, int centerZ, int radius)
    {
        yield return (centerX, centerZ);
        for (var ring = 1; ring <= radius; ring++)
        {
            for (var dx = -ring; dx <= ring; dx++)
                yield return (centerX + dx, centerZ - ring);
            for (var dz = -ring + 1; dz <= ring; dz++)
                yield return (centerX + ring, centerZ + dz);
            for (var dx = ring - 1; dx >= -ring; dx--)
                yield return (centerX + dx, centerZ + ring);
            for (var dz = ring - 1; dz >= -ring + 1; dz--)
                yield return (centerX - ring, centerZ + dz);
        }
    }

    public ValueTask StopGenerationAsync() => _generationBroker.DisposeAsync();

    public static int AirRuntimeId => Blocks.Air;

    // ---- blocks ----

    /// <summary>The block at a cell; air outside the world's height. Loads the column when it is not resident (see <see cref="SyncLoadCount"/>).</summary>
    public int GetBlock(int x, int y, int z) =>
        WorldColumn.InRange(y) ? ColumnAt(x, z).Get(x, y, z) : Blocks.Air;

    /// <summary>The block at a cell only if its column is resident — what ticking systems use so they never wake a sleeping chunk.</summary>
    public bool TryGetBlock(int x, int y, int z, out int runtimeId)
    {
        runtimeId = Blocks.Air;
        if (!WorldColumn.InRange(y)) return true;
        if (!_columns.TryGetValue(new ChunkCoord(ToChunk(x), ToChunk(z)), out var column)) return false;
        runtimeId = column.Get(x, y, z);
        return true;
    }

    /// <summary>Whether the column holding block (x, z) is resident.</summary>
    public bool IsLoaded(int x, int z) => _columns.ContainsKey(new ChunkCoord(ToChunk(x), ToChunk(z)));

    /// <summary>Writes a block and queues its neighbours for re-evaluation. False only outside the world's height.</summary>
    public bool TrySetBlock(int x, int y, int z, int blockRuntimeId) =>
        TrySetBlock(x, y, z, blockRuntimeId, SetBlockFlags.Default);

    /// <summary>As above; <paramref name="flags"/> says what the write sets in motion (see <see cref="SetBlockFlags"/>).</summary>
    public bool TrySetBlock(int x, int y, int z, int blockRuntimeId, SetBlockFlags flags)
    {
        if (!WorldColumn.InRange(y)) return false;
        ColumnAt(x, z).Set(x, y, z, blockRuntimeId);
        if ((flags & SetBlockFlags.NotifyNeighbors) != 0) _ = BlockUpdates.Enqueue(x, y, z);
        return true;
    }

    /// <summary>
    /// Setup-time write (world seeding, benchmarks, tests): a refusal is a bug in the caller, so it throws instead of dropping the
    /// edit. Gameplay uses <see cref="TrySetBlock"/> and reacts to the refusal.
    /// </summary>
    public void SetBlock(int x, int y, int z, int blockRuntimeId)
    {
        if (!TrySetBlock(x, y, z, blockRuntimeId))
            throw new InvalidOperationException($"Block {x},{y},{z} is outside the world's height ({WorldColumn.MinY}..{WorldColumn.MaxY}).");
    }

    // ---- block entities ----

    /// <summary>The block entity of a cell, or null. Loads the column when it is not resident.</summary>
    public BlockEntity? GetBlockEntity(int x, int y, int z) =>
        WorldColumn.InRange(y) && ColumnAt(x, z).TryGetEntity(x, y, z, out var entity) ? entity : null;

    public bool TryGetBlockEntity<T>(int x, int y, int z, out T entity) where T : BlockEntity
    {
        if (GetBlockEntity(x, y, z) is T typed)
        {
            entity = typed;
            return true;
        }

        entity = null!;
        return false;
    }

    /// <summary>Attaches an entity to a cell (replacing any), and marks its column for saving.</summary>
    public void SetBlockEntity(int x, int y, int z, BlockEntity entity) => ColumnAt(x, z).SetEntity(x, y, z, entity);

    public bool RemoveBlockEntity(int x, int y, int z, out BlockEntity entity) =>
        ColumnAt(x, z).RemoveEntity(x, y, z, out entity);

    /// <summary>Tells the world a block entity's contents changed, so its column is saved at the next sweep.</summary>
    public void MarkBlockEntityDirty(int x, int z) => ColumnAt(x, z).MarkDirty();

    // ---- persistence and residency ----

    /// <summary>Encodes and queues up to <paramref name="budget"/> edited columns for the disk. Returns how many were written.</summary>
    public int PersistDirtyColumns(int budget)
    {
        var written = 0;
        foreach (var column in _columns.Values)
        {
            if (written >= budget) break;
            if (!column.IsDirty) continue;
            PersistColumn(column);
            written++;
        }

        return written;
    }

    private void PersistColumn(WorldColumn column)
    {
        // Cleared before encoding: an edit that lands while the blob is being built marks it dirty again.
        column.ClearDirty();
        var blob = ColumnCodec.Encode(column, Blocks.Palette);
        WriteBehind(_storage.PutColumnAsync(column.Coord, blob), "PutColumn");
    }

    /// <summary>Snapshot of resident chunk coords — the eviction sweep's candidate set.</summary>
    public List<(int X, int Z)> CopyLoadedColumns()
    {
        var list = new List<(int X, int Z)>(_columns.Count);
        foreach (var key in _columns.Keys)
            list.Add((key.X, key.Z));
        return list;
    }

    /// <summary>
    /// Drops chunk (chunkX, chunkZ) from RAM when no viewer, floor item or open container needs it (ADR §114). An edited
    /// column is queued for the disk first; one nobody touched is simply forgotten and regenerated if it is ever needed
    /// again. Returns false without changing anything while something still needs the column.
    /// </summary>
    public bool TryEvictChunk(int chunkX, int chunkZ)
    {
        if (ChunkResidency.HasViewers(chunkX, chunkZ) || FloorDrops.HasEntitiesInChunk(chunkX, chunkZ))
            return false;
        if (!_columns.TryGetValue(new ChunkCoord(chunkX, chunkZ), out var column))
            return true;
        if (HasOpenContainer(column))
            return false;

        if (column.IsDirty) PersistColumn(column);
        _columns.TryRemove(column.Coord, out _);
        return true;
    }

    private static bool HasOpenContainer(WorldColumn column)
    {
        var open = false;
        column.ForEachEntity((_, _, _, entity) => open |= entity is ContainerEntity { Openers.Count: > 0 });
        return open;
    }

    /// <summary>Residency line for operators: columns and block entities resident versus ZLDB's own always-resident dataset.</summary>
    public void LogResidencySnapshot()
    {
        if (_logger is null) return;
        var zldbEntries = _storage.TryGetProperty("zldb.num-entries", out var entries) ? entries : "n/a";
        var blockEntities = 0;
        foreach (var column in _columns.Values) blockEntities += column.EntityCount;
        _logger.Info(
            $"Chunk residency: {_columns.Count} columns / {blockEntities} block entities resident in RAM " +
            $"(sync loads {SyncLoadCount}; zldb.num-entries={zldbEntries}, mixes every key kind).");
    }

    private static int ToChunk(int block) => ChunkMath.BlockToChunk(block);
}
